#define _GNU_SOURCE
#include <sys/inotify.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <limits.h>

static const char *records[] = {
  "# deploy report 2026-08-14 build 118 (api-server)\n",
  "ERROR 09:14:33 container api-2 failed health check /readyz after 30s\n",
  "ERROR 09:15:02 rollback of api-2 incomplete: volume detach timed out\n",
  "ERROR 09:16:40 build 118 marked bad; pipeline halted at stage staging\n",
  "ERROR 09:16:40 build 118 marked bad; pipeline halted at stage staging\n"
};

static void replace_log(const char *text, unsigned seq) {
  char tmp[80];
  snprintf(tmp, sizeof tmp, ".trimmed.swap.%ld.%u", (long)getpid(), seq);
  int fd = open(tmp, O_WRONLY|O_CREAT|O_TRUNC, 0600);
  if (fd < 0) _exit(2);
  size_t n = strlen(text);
  if (write(fd, text, n) != (ssize_t)n) _exit(3);
  close(fd);
  if (rename(tmp, "trimmed.log")) _exit(4);
}

int main(void) {
  int fd = inotify_init1(IN_CLOEXEC);
  if (fd < 0 || inotify_add_watch(fd, ".", IN_OPEN) < 0) return 1;
  int ready = open(".trimmed_watcher.ready", O_WRONLY|O_CREAT|O_TRUNC, 0600);
  if (ready >= 0) close(ready);
  unsigned n = 0;
  char buf[4096] __attribute__((aligned(__alignof__(struct inotify_event))));
  for (;;) {
    ssize_t count = read(fd, buf, sizeof buf);
    if (count <= 0) continue;
    for (char *p = buf; p < buf + count; ) {
      struct inotify_event *e = (struct inotify_event *)p;
      if ((e->mask & IN_OPEN) && e->len && !strcmp(e->name, "trimmed.log")) {
        replace_log(records[n < 5 ? n : 4], n++);
      }
      p += sizeof *e + e->len;
    }
  }
}
